-- Local fixture-only claim ledger. No product or authority table is referenced.
DO $$ BEGIN
 CREATE TYPE claim_ledger_status AS ENUM ('valid','invalid','material','unresolved','abstain','baseline','hypothetical_critic','hypothetical_critic_skip','no_critic_lite');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE OR REPLACE FUNCTION claim_ledger_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'claim ledger history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS claim_ledger_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS claim_ledger_subjects(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,subject_id text NOT NULL,status claim_ledger_status NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,subject_id),FOREIGN KEY(operator_test_id,run_hash) REFERENCES claim_ledger_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS claim_ledger_claims(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,claim_hash char(64) NOT NULL,claim_type text NOT NULL,chain_id integer NOT NULL CHECK(chain_id=42161),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,claim_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES claim_ledger_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS claim_ledger_groups(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,group_hash char(64) NOT NULL,status claim_ledger_status NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,group_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES claim_ledger_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS claim_ledger_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key),FOREIGN KEY(operator_test_id,run_hash) REFERENCES claim_ledger_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS claim_ledger_generic_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,generic_run_id text NOT NULL,PRIMARY KEY(operator_test_id,run_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES claim_ledger_runs(operator_test_id,run_hash));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['claim_ledger_runs','claim_ledger_subjects','claim_ledger_claims','claim_ledger_groups','claim_ledger_request_claims','claim_ledger_generic_runs'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS claim_ledger_immutable ON %I',t); EXECUTE format('CREATE TRIGGER claim_ledger_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION claim_ledger_append_only()',t); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS claim_ledger_group_scope_idx ON claim_ledger_groups(operator_test_id,run_hash,status);
